1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	  moonstone: 25,
8	};
9	
10	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
11	
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_PRICE = 60;
14	
15	const COMPONENT_TYPES = ["rune", "moonstone"];
16	
17	const sumBy = <T>(items: T[], amount: (item: T) => number): number =>
18	  items.reduce((sum, item) => sum + amount(item), 0);
19	
20	const sumOfItemPrices = (items: Item[]): number =>
21	  sumBy(items, (item) => priceList[item.type]);
22	
23	const countOf = (type: string, items: Item[]): number =>
24	  items.filter((item) => item.type === type).length;
25	
26	const componentPremium = (type: string, items: Item[]): number => {
27	  const count = countOf(type, items);
28	  return count === COMPONENT_BLOCK_SIZE
29	    ? COMPONENT_BLOCK_PRICE
30	    : count * priceList[type];
31	};
32	
33	export const basePremium = (items: Item[]): number => {
34	  const nonComponents = items.filter(
35	    (item) => !COMPONENT_TYPES.includes(item.type),
36	  );
37	  const componentsTotal = COMPONENT_TYPES.reduce(
38	    (total, type) => total + componentPremium(type, items),
39	    0,
40	  );
41	  return sumOfItemPrices(nonComponents) + componentsTotal;
42	};
43	
44	const PROCESSING_FEE = 5;
45	const CURSE_SURCHARGE_RATE = 0.5;
46	const HIGH_ENCHANTMENT_RATE = 0.3;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	const FIRST_INSURANCE_RATE = 0.1;
49	const LOYALTY_DISCOUNT_RATE = 0.2;
50	const LOYALTY_THRESHOLD_YEARS = 2;
51	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
52	
53	type Customer = { yearsWithMHPCO: number };
54	
55	const curseSurchargeFor = (item: Item): number =>
56	  item.cursed ? basePremium([item]) * CURSE_SURCHARGE_RATE : 0;
57	
58	const enchantSurchargeFor = (item: Item): number =>
59	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
60	    ? basePremium([item]) * HIGH_ENCHANTMENT_RATE
61	    : 0;
62	
63	const surchargesFor = (item: Item): number =>
64	  curseSurchargeFor(item) + enchantSurchargeFor(item);
65	
66	// Premiums round in MHPCO's favor — up. (Claim payouts round down, also in MHPCO's favor.)
67	const roundInFavorUp = (amount: number): number => Math.ceil(amount);
68	
69	// Claim payouts round in MHPCO's favor — down.
70	const roundInFavorDown = (amount: number): number => Math.floor(amount);
71	
72	const quotePremium = (
73	  items: Item[],
74	  customer: Customer,
75	  isFollowUp: boolean,
76	): number => {
77	  const policyBase = basePremium(items);
78	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_RATE;
79	  const loyaltyDiscount =
80	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
81	      ? policyBase * LOYALTY_DISCOUNT_RATE
82	      : 0;
83	  const followUpDiscount = isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
84	  const policyCharges =
85	    policyBase + firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
86	
87	  const itemSurcharges = sumBy(items, surchargesFor);
88	
89	  return roundInFavorUp(policyCharges + itemSurcharges + PROCESSING_FEE);
90	};
91	
92	const insuranceValueList: Record<string, number> = {
93	  sword: 1000,
94	  amulet: 600,
95	  staff: 800,
96	  potion: 400,
97	  rune: 250,
98	  moonstone: 250,
99	};
100	
101	const CAP_MULTIPLIER = 2;
102	const DEDUCTIBLE = 100;
103	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
104	const HIGH_ENCHANTMENT_PAYOUT_RATE = 0.5;
105	
106	const insuranceSum = (items: Item[]): number =>
107	  sumBy(items, (item) => insuranceValueList[item.type]);
108	
109	type Damage = { itemType: string; amount: number };
110	
111	const isHighlyEnchanted = (item: Item | undefined): boolean =>
112	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_PAYOUT_THRESHOLD;
113	
114	const coveredAmountFor = (damage: Damage, insuredItem: Item | undefined): number =>
115	  isHighlyEnchanted(insuredItem)
116	    ? damage.amount * HIGH_ENCHANTMENT_PAYOUT_RATE
117	    : damage.amount;
118	
119	const reimbursementFor = (damage: Damage, items: Item[]): number => {
120	  const insuredItem = items.find((item) => item.type === damage.itemType);
121	  return coveredAmountFor(damage, insuredItem) - DEDUCTIBLE;
122	};
123	
124	type Incident = { cause: string; damages: Damage[] };
125	
126	type QuoteStep = { op: "quote"; items: Item[] };
127	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
128	type Step = QuoteStep | ClaimStep;
129	type Scenario = { customer: Customer; steps: Step[] };
130	
131	type Policy = { items: Item[]; remainingCap: number };
132	type QuoteResult = { premium: number };
133	type ClaimResult = { payout: number; remainingCap: number };
134	type StepResult = QuoteResult | ClaimResult;
135	
136	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
137	  const policies: Record<number, Policy> = {};
138	  let quoteCount = 0;
139	
140	  const handleQuote = (step: QuoteStep, index: number): QuoteResult => {
141	    const isFollowUp = quoteCount > 0;
142	    quoteCount += 1;
143	    policies[index] = {
144	      items: step.items,
145	      remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
146	    };
147	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
148	  };
149	
150	  const handleClaim = (step: ClaimStep): ClaimResult => {
151	    const policy = policies[step.policy];
152	    const payout = roundInFavorDown(
153	      sumBy(step.incident.damages, (damage) =>
154	        reimbursementFor(damage, policy.items),
155	      ),
156	    );
157	    policy.remainingCap -= payout;
158	    return { payout, remainingCap: policy.remainingCap };
159	  };
160	
161	  const results = scenario.steps.map((step, index): StepResult =>
162	    step.op === "quote" ? handleQuote(step, index) : handleClaim(step),
163	  );
164	
165	  return { results };
166	};
